1	import Link from "next/link";
2	import { formatDownloads, type ModSummary } from "@/lib/mods-catalog";
3	import { GameBadge } from "./GameBadge";
4	import { IconDownload, IconStar } from "./icons";
5	
6	/**
7	 * One catalogue tile. Plain <img>, not next/image — the icon/gallery URLs
8	 * come from whichever source verified the mod (cdn.modrinth.com,
9	 * spigotmc.org, gcdn.thunderstore.io, ...), and next/image requires every
10	 * remote host to be allow-listed up front. The CSP already permits
11	 * `img-src https:`, so a plain tag renders every one of them with no
12	 * per-CDN config to maintain as new sources get verified.
13	 *
14	 * `showGameBadge` is for CROSS-GAME grids only (the homepage's mixed
15	 * featured/trending strips) — a single game's own page never sets it, the
16	 * game already being obvious from context there.
17	 */
18	export function ModCard({
19	  mod,
20	  href,
21	  showGameBadge = false,
22	}: {
23	  mod: ModSummary;
24	  href: string;
25	  showGameBadge?: boolean;
26	}) {
27	  const downloads = formatDownloads(mod.downloads);
28	  return (
29	    <Link href={href} className="card card-hover group flex flex-col gap-0 overflow-hidden !p-0">
30	      <div className="relative aspect-[16/10] w-full shrink-0 overflow-hidden bg-white/[0.04]">
31	        {mod.iconUrl ? (
32	          // eslint-disable-next-line @next/next/no-img-element
33	          <img
34	            src={mod.iconUrl}
35	            alt=""
36	            loading="lazy"
37	            className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.04]"
38	          />
39	        ) : (
40	          <div className="flex h-full w-full items-center justify-center text-3xl font-bold text-[var(--fg-muted)]">
41	            {mod.name.slice(0, 1)}
42	          </div>
43	        )}
44	        {mod.featured && (
45	          <span className="absolute left-2 top-2 rounded-full bg-brand-500/90 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
46	            Featured
47	          </span>
48	        )}
49	        {mod.avgRating != null && (
50	          <span className="absolute right-2 top-2 flex items-center gap-1 rounded-full bg-black/60 px-2 py-0.5 text-[11px] font-semibold text-amber-300">
51	            <IconStar size={11} filled />
52	            {mod.avgRating.toFixed(1)}
53	          </span>
54	        )}
55	        {showGameBadge && <GameBadge family={mod.gameFamily} />}
56	      </div>
57	
58	      <div className="flex flex-1 flex-col gap-2 p-4">
59	        <div className="flex items-center gap-1.5 text-[11px] font-medium uppercase tracking-wide text-brand-300">
60	          {mod.gameFamilyLabel} <span className="text-[var(--fg-muted)]">· {mod.category}</span>
61	        </div>
62	        <h3 className="truncate text-sm font-semibold text-[var(--fg)] group-hover:text-brand-300">{mod.name}</h3>
63	        {mod.description && <p className="line-clamp-2 text-xs leading-relaxed text-[var(--fg-muted)]">{mod.description}</p>}
64	        <div className="mt-auto flex items-center justify-between pt-1 text-[11px] text-[var(--fg-muted)]">
65	          <span className="flex items-center gap-1">
66	            {downloads && (
67	              <>
68	                <IconDownload size={12} /> {downloads}
69	              </>
70	            )}
71	          </span>
72	          {mod.verified && <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-emerald-400">Verified</span>}
73	        </div>
74	      </div>
75	    </Link>
76	  );
77	}
