1	import Link from "next/link";
2	import type { ModSummary } from "@/lib/mods-catalog";
3	import type { CatalogSort } from "@/lib/mods-catalog";
4	import { buildHref } from "@/lib/pagination";
5	import { ModCard } from "./ModCard";
6	import { QuickAddButton, type QuickAddServer } from "./QuickAddButton";
7	import { IconSearch, IconArrow } from "./icons";
8	
9	/**
10	 * The interactive core of NxLabs's browse experience — search, chip
11	 * filtering, sort, and paging. Until 2026-09-19 all four ran client-side
12	 * (`useState`/`useMemo`) over the whole array the server component fetched
13	 * up front, which was genuinely fine at ~124 hand-seeded rows and quietly
14	 * broken the moment a real bulk import (scripts/import-modrinth-catalog.ts)
15	 * landed 32,000+ rows in one family: the server capped what it fetched at
16	 * 400, so there was no page 2 at all, AND the search box's own placeholder
17	 * ("Search mods, plugins, and more…") promises to search the catalogue, not
18	 * whatever 400-or-fewer rows happened to already be loaded — a client-side
19	 * `.filter()` over a partial array would silently under-report or entirely
20	 * miss real matches outside that window.
21	 *
22	 * So this is now a Server Component: `mods` is just the current page,
23	 * already filtered/sorted/paginated by `lib/mods-catalog.ts`'s
24	 * `queryCatalogMods()`, and every control here is a plain link or a native
25	 * GET `<form>` that re-requests the page with new searchParams — the same
26	 * pattern this codebase already uses for /blog's search+pager
27	 * (app/blog/page.tsx) and the admin tables (lib/pagination.ts). No client
28	 * JS is required for the store to work at all; QuickAddButton (the one
29	 * genuinely interactive bit — installing onto a real server) stays its own
30	 * small Client Component underneath.
31	 */
32	export type SortKey = CatalogSort;
33	
34	const SORTS: { key: SortKey; label: string }[] = [
35	  { key: "featured", label: "Featured" },
36	  { key: "downloads", label: "Most Downloaded" },
37	  { key: "latest", label: "Latest" },
38	  { key: "rating", label: "Top Rated" },
39	];
40	
41	export function StoreBrowser({
42	  mods,
43	  total,
44	  page,
45	  totalPages,
46	  perPage,
47	  chips,
48	  chipField,
49	  activeChipKey,
50	  basePath,
51	  browsePath,
52	  q,
53	  sort,
54	  showGameBadge = false,
55	  serversByFamily,
56	  deployHref,
57	  searchPlaceholder = "Search mods, plugins, and more…",
58	  emptyLabel = "No mods match your filters yet.",
59	}: {
60	  /** The current page's rows only — already the real, server-side filtered/sorted/paginated set. */
61	  mods: ModSummary[];
62	  /** Real total row count for the active filters (not just this page). */
63	  total: number;
64	  page: number;
65	  totalPages: number;
66	  perPage: number;
67	  /**
68	   * Real, DB-wide counts (never derived from `mods`, which is only one
69	   * page). When `href` is set, the chip navigates to a different route
70	   * entirely (the cross-game pages point family chips at the real
71	   * `/games/[family]` pages instead of re-filtering in place); otherwise it
72	   * links to this same route with `?category=` set.
73	   */
74	  chips: { key: string; label: string; count: number; href?: string }[];
75	  chipField: "gameFamily" | "category";
76	  /** Which chip (by key) is the active filter — only meaningful when chipField is "category"; gameFamily chips always navigate away instead. */
77	  activeChipKey?: string;
78	  /** Detail-page route prefix — `${basePath}/${mod.gameFamily}/${mod.slug}`. */
79	  basePath: string;
80	  /**
81	   * This BROWSE page's own path (no query string) — search/sort/chip/pager
82	   * links are all built from it. Usually the same as `basePath` (the two
83	   * cross-game homepages), but the per-family pages keep mod detail links
84	   * under the shared `/mods/[family]/[slug]` (or portal equivalent) route
85	   * while this page itself lives at `/mods/games/[family]` — hence the split.
86	   */
87	  browsePath?: string;
88	  /** Current `?q=`. */
89	  q?: string;
90	  /** Current `?sort=`. */
91	  sort?: SortKey;
92	  showGameBadge?: boolean;
93	  /** Portal only: this viewer's eligible servers per game family, for the QuickAddButton row. */
94	  serversByFamily?: Record<string, QuickAddServer[]>;
95	  /** Portal only: where "order one" points when there's no matching server. */
96	  deployHref?: string;
97	  searchPlaceholder?: string;
98	  emptyLabel?: string;
99	}) {
100	  const activeSort = sort ?? "featured";
101	  const query = q ?? "";
102	  const ownPath = browsePath ?? basePath;
103	
104	  /** Build a link on this same route, preserving q/sort/category unless overridden. Omitting `page` resets to page 1 — the right default whenever the filter itself changes. */
105	  const hrefFor = (next: { page?: number; sort?: SortKey; category?: string | null; q?: string }) =>
106	    buildHref(ownPath, {
107	      q: next.q ?? query,
108	      sort: (next.sort ?? activeSort) === "featured" ? undefined : (next.sort ?? activeSort),
109	      category: next.category === null ? undefined : (next.category ?? activeChipKey),
110	      page: next.page ?? 1,
111	    });
112	
113	  const rangeFrom = total === 0 ? 0 : (page - 1) * perPage + 1;
114	  const rangeTo = total === 0 ? 0 : Math.min(page * perPage, total);
115	
116	  return (
117	    <div>
118	      <div className="mb-5 flex flex-col gap-3 sm:flex-row sm:items-center sm:justify-between">
119	        <form method="get" action={ownPath} className="relative w-full sm:max-w-xs">
120	          <IconSearch
121	            className="pointer-events-none absolute left-3 top-1/2 -translate-y-1/2 text-[var(--fg-muted)]"
122	            size={16}
123	          />
124	          <input
125	            type="search"
126	            name="q"
127	            defaultValue={query}
128	            placeholder={searchPlaceholder}
129	            aria-label="Search mods"
130	            className="input w-full pl-9 text-sm"
131	          />
132	          {activeSort !== "featured" && <input type="hidden" name="sort" value={activeSort} />}
133	          {chipField === "category" && activeChipKey && <input type="hidden" name="category" value={activeChipKey} />}
134	        </form>
135	        <div className="flex flex-wrap gap-1 rounded-full border border-white/10 p-1">
136	          {SORTS.map((s) => (
137	            <Link
138	              key={s.key}
139	              href={hrefFor({ sort: s.key })}
140	              className={`rounded-full px-3 py-1.5 text-xs font-medium transition-colors ${
141	                activeSort === s.key ? "bg-brand-500 text-white" : "text-[var(--fg-muted)] hover:text-[var(--fg)]"
142	              }`}
143	            >
144	              {s.label}
145	            </Link>
146	          ))}
147	        </div>
148	      </div>
149	
150	      {chips.length > 0 && (
151	        <div className="mb-6 flex flex-wrap gap-2">
152	          <Link
153	            href={chipField === "gameFamily" ? ownPath : hrefFor({ category: null })}
154	            className={`rounded-full border px-4 py-1.5 text-sm ${
155	              !activeChipKey ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
156	            }`}
157	          >
158	            All
159	          </Link>
160	          {chips.map((c) => (
161	            <Link
162	              key={c.key}
163	              href={c.href ?? hrefFor({ category: c.key })}
164	              className={`rounded-full border px-4 py-1.5 text-sm ${
165	                activeChipKey === c.key ? "border-brand-400 bg-brand-500/10 text-brand-300" : "border-white/10 text-[var(--fg-muted)] hover:border-white/20"
166	              }`}
167	            >
168	              {c.label} ({c.count})
169	            </Link>
170	          ))}
171	        </div>
172	      )}
173	
174	      {mods.length === 0 ? (
175	        <p className="py-12 text-center text-sm text-[var(--fg-muted)]">{emptyLabel}</p>
176	      ) : (
177	        <>
178	          <div className="grid grid-cols-1 gap-4 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4">
179	            {mods.map((mod) => {
180	              const matching = serversByFamily?.[mod.gameFamily] ?? [];
181	              return (
182	                <div key={mod.id} className="flex flex-col gap-2">
183	                  <ModCard mod={mod} href={`${basePath}/${mod.gameFamily}/${mod.slug}`} showGameBadge={showGameBadge} />
184	                  {serversByFamily &&
185	                    (matching.length > 0 ? (
186	                      <QuickAddButton modId={mod.id} servers={matching} />
187	                    ) : (
188	                      <p className="text-xs text-tx-mute">
189	                        No matching server yet —{" "}
190	                        <a href={deployHref ?? "/dashboard/deploy"} className="text-brand-300 underline underline-offset-2">
191	                          order one
192	                        </a>
193	                        .
194	                      </p>
195	                    ))}
196	                </div>
197	              );
198	            })}
199	          </div>
200	
201	          <Pager page={page} totalPages={totalPages} total={total} rangeFrom={rangeFrom} rangeTo={rangeTo} hrefFor={hrefFor} />
202	        </>
203	      )}
204	    </div>
205	  );
206	}
207	
208	/** Real Prev/Next + numbered pager, plus honest "X–Y of N mods" copy — no fake page counts. */
209	function Pager({
210	  page,
211	  totalPages,
212	  total,
213	  rangeFrom,
214	  rangeTo,
215	  hrefFor,
216	}: {
217	  page: number;
218	  totalPages: number;
219	  total: number;
220	  rangeFrom: number;
221	  rangeTo: number;
222	  hrefFor: (next: { page: number }) => string;
223	}) {
224	  const linkCls =
225	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/10 bg-white/[0.03] px-3 text-sm font-medium text-[var(--fg-muted)] transition-colors hover:border-brand-400/50 hover:text-[var(--fg)]";
226	  const disabledCls =
227	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/[0.06] bg-transparent px-3 text-sm font-medium text-[var(--fg-muted)]/40 cursor-not-allowed";
228	
229	  const windowStart = Math.max(1, page - 2);
230	  const windowEnd = Math.min(totalPages, page + 2);
231	  const pages: number[] = [];
232	  for (let i = windowStart; i <= windowEnd; i++) pages.push(i);
233	
234	  return (
235	    <div className="mt-8 flex flex-col items-center gap-3">
236	      <p className="text-xs text-[var(--fg-muted)]">
237	        {total === 0 ? "0 mods" : `${rangeFrom.toLocaleString()}–${rangeTo.toLocaleString()} of ${total.toLocaleString()} mods`}
238	      </p>
239	      {totalPages > 1 && (
240	        <nav className="flex flex-wrap items-center justify-center gap-2" aria-label="Mods pagination">
241	          {page > 1 ? (
242	            <Link href={hrefFor({ page: page - 1 })} rel="prev" className={linkCls} aria-label="Previous page">
243	              <IconArrow size={13} className="rotate-180" /> Prev
244	            </Link>
245	          ) : (
246	            <span className={disabledCls} aria-hidden>
247	              <IconArrow size={13} className="rotate-180" /> Prev
248	            </span>
249	          )}
250	
251	          {windowStart > 1 && (
252	            <>
253	              <Link href={hrefFor({ page: 1 })} className={linkCls}>
254	                1
255	              </Link>
256	              {windowStart > 2 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
257	            </>
258	          )}
259	
260	          {pages.map((n) =>
261	            n === page ? (
262	              <span
263	                key={n}
264	                aria-current="page"
265	                className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-brand-500/50 bg-brand-500/15 px-3 text-sm font-semibold text-brand-300"
266	              >
267	                {n}
268	              </span>
269	            ) : (
270	              <Link key={n} href={hrefFor({ page: n })} className={linkCls}>
271	                {n}
272	              </Link>
273	            )
274	          )}
275	
276	          {windowEnd < totalPages && (
277	            <>
278	              {windowEnd < totalPages - 1 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
279	              <Link href={hrefFor({ page: totalPages })} className={linkCls}>
280	                {totalPages}
281	              </Link>
282	            </>
283	          )}
284	
285	          {page < totalPages ? (
286	            <Link href={hrefFor({ page: page + 1 })} rel="next" className={linkCls} aria-label="Next page">
287	              Next <IconArrow size={13} />
288	            </Link>
289	          ) : (
290	            <span className={disabledCls} aria-hidden>
291	              Next <IconArrow size={13} />
292	            </span>
293	          )}
294	        </nav>
295	      )}
296	    </div>
297	  );
298	}
