1	import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
2	
3	/**
4	 * Small game-identifier overlay for a ModCard shown in a CROSS-GAME grid
5	 * (the homepage's featured/trending strips, mixing mods from every family).
6	 * Uses the same real per-game square logo GameCoverTile/GameLogo fall back to
7	 * (`/logos/games/<family>.png`) — never a drawn/procedural stand-in — so the
8	 * badge always matches the game's real branding everywhere else in the app.
9	 *
10	 * NOT rendered on a single game's own dedicated page (app/**\/nxlabs/games/[family])
11	 * — there the game is already the page, so the badge would be redundant.
12	 */
13	export function GameBadge({ family, className = "" }: { family: string; className?: string }) {
14	  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
15	  return (
16	    <span
17	      title={label}
18	      className={
19	        "absolute bottom-1.5 left-1.5 flex h-6 w-6 items-center justify-center overflow-hidden rounded-md border border-white/20 bg-navy-950/80 shadow-md " +
20	        className
21	      }
22	    >
23	      {/* eslint-disable-next-line @next/next/no-img-element */}
24	      <img src={`/logos/games/${family}.png`} alt={label} className="h-full w-full object-contain p-0.5" />
25	    </span>
26	  );
27	}
