1	"use client";
2	
3	import { useState, useTransition } from "react";
4	import { installMod } from "@/lib/actions-mods";
5	
6	export type QuickAddServer = { id: string; hostname: string; label: string | null };
7	
8	/**
9	 * The /dashboard/nxlabs card's install control. Unlike AddToServerWidget
10	 * (which fetches eligibility client-side because it also has to work for an
11	 * anonymous visitor on the public /mods pages), the dashboard already knows
12	 * who's logged in and has computed each mod's matching servers server-side in
13	 * one query for the whole grid — so this just renders what it's given and
14	 * calls the same installMod() action. One install code path either way.
15	 */
16	export function QuickAddButton({ modId, servers }: { modId: string; servers: QuickAddServer[] }) {
17	  const [pending, startTransition] = useTransition();
18	  const [serverId, setServerId] = useState(servers[0]?.id ?? "");
19	  const [result, setResult] = useState<{ ok?: boolean; error?: string } | null>(null);
20	
21	  if (servers.length === 0) return null;
22	
23	  if (result?.ok) {
24	    return <p className="text-xs text-emerald-400">Queued for install.</p>;
25	  }
26	
27	  return (
28	    <div className="flex flex-col gap-1.5">
29	      <div className="flex items-center gap-1.5">
30	        {servers.length > 1 ? (
31	          <select className="input py-1 text-xs" value={serverId} onChange={(e) => setServerId(e.target.value)} disabled={pending}>
32	            {servers.map((s) => (
33	              <option key={s.id} value={s.id}>
34	                {s.label || s.hostname}
35	              </option>
36	            ))}
37	          </select>
38	        ) : (
39	          <span className="truncate text-xs text-[var(--fg-muted)]">{servers[0].label || servers[0].hostname}</span>
40	        )}
41	        <button
42	          className="btn-primary py-1 text-xs"
43	          disabled={pending}
44	          onClick={() =>
45	            startTransition(async () => {
46	              setResult(null);
47	              const res = await installMod(serverId, modId);
48	              setResult(res);
49	            })
50	          }
51	        >
52	          {pending ? "Adding…" : "Add to server"}
53	        </button>
54	      </div>
55	      {result?.error && <p className="text-xs text-red-400">{result.error}</p>}
56	    </div>
57	  );
58	}
