1	"use client";
2	
3	import { useEffect, useState, useTransition } from "react";
4	import Link from "next/link";
5	import { getEligibleServersForMod, installMod, type EligibleServer } from "@/lib/actions-mods";
6	
7	/**
8	 * "Add to my server" — the one piece of NxLabs that differs between an
9	 * anonymous visitor and a signed-in customer with a matching server. Used on
10	 * BOTH the public mod detail page and the logged-in /dashboard/nxlabs page,
11	 * so the three states (anonymous / no matching server / pick-and-install)
12	 * only exist once. Installing always goes through the real installMod()
13	 * server action — nothing here talks to a server directly.
14	 */
15	export function AddToServerWidget({ modId, gameFamily, downloadUrl }: { modId: string; gameFamily: string; downloadUrl: string | null }) {
16	  const [loading, setLoading] = useState(true);
17	  const [loggedIn, setLoggedIn] = useState(false);
18	  const [servers, setServers] = useState<EligibleServer[]>([]);
19	  const [selected, setSelected] = useState<string>("");
20	  const [pending, startTransition] = useTransition();
21	  const [result, setResult] = useState<{ ok?: boolean; error?: string } | null>(null);
22	
23	  useEffect(() => {
24	    let cancelled = false;
25	    getEligibleServersForMod(modId).then((res) => {
26	      if (cancelled) return;
27	      setLoggedIn(res.loggedIn);
28	      setServers(res.servers);
29	      setSelected(res.servers[0]?.id ?? "");
30	      setLoading(false);
31	    });
32	    return () => {
33	      cancelled = true;
34	    };
35	  }, [modId]);
36	
37	  if (loading) {
38	    return <div className="h-11 w-full animate-pulse rounded-lg bg-white/[0.06]" />;
39	  }
40	
41	  if (!loggedIn) {
42	    return (
43	      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-white/10 bg-white/[0.03] p-4">
44	        <p className="text-sm text-[var(--fg-muted)]">
45	          <Link href={`/login?next=/mods`} className="text-brand-300 underline underline-offset-2">
46	            Log in
47	          </Link>{" "}
48	          to add this straight to one of your {gameFamily} servers, or download it directly below.
49	        </p>
50	      </div>
51	    );
52	  }
53	
54	  if (servers.length === 0) {
55	    return (
56	      <div className="flex flex-wrap items-center gap-3 rounded-lg border border-white/10 bg-white/[0.03] p-4">
57	        <p className="text-sm text-[var(--fg-muted)]">
58	          You don&apos;t have a matching {gameFamily} server yet.{" "}
59	          <Link href="/dashboard/deploy" className="text-brand-300 underline underline-offset-2">
60	            Order one
61	          </Link>{" "}
62	          to install this in one click next time, or download it directly below.
63	        </p>
64	      </div>
65	    );
66	  }
67	
68	  return (
69	    <div className="rounded-lg border border-white/10 bg-white/[0.03] p-4">
70	      <div className="flex flex-wrap items-center gap-3">
71	        <select
72	          className="input max-w-xs"
73	          value={selected}
74	          onChange={(e) => setSelected(e.target.value)}
75	          disabled={pending}
76	        >
