import { GAME_DISPLAY, type GameFamily } from "@/lib/games";
import { resolveBadgeArt, getPosterAccentColor } from "@/lib/game-poster-color";

/**
 * Game-identifier overlay for a ModCard shown in a CROSS-GAME grid (the
 * homepage's featured/trending strips, mixing mods from every family).
 *
 * 2026-09-20: was a 24x24 square crop of the flat wordmark logo — the
 * owner's exact complaint reviewing a live screenshot was "so small you
 * can't even see it". Now renders the game's real portrait box art
 * (`GAME_ART_SLUG[family].poster`, the same asset GameCoverTile/the
 * game-servers carousel use — never a drawn/procedural stand-in) at a size
 * that's actually readable, with a border color genuinely sampled from that
 * same art file (see lib/game-poster-color.ts) rather than a hand-picked hex.
 * Falls back to the hero still, then the old square wordmark, for the
 * handful of "Wave 3 SCAFFOLD" families in GAME_ART_SLUG that don't have
 * real key-art yet.
 *
 * Async Server Component — fine to render directly inside ModCard, itself a
 * Server Component; both the color sample and the file-exists check are
 * cached (poster art) / already just a network-free disk read.
 *
 * NOT rendered on a single game's own dedicated page (app/**\/nxlabs/games/[family])
 * — there the game is already the page, so the badge would be redundant.
 */
export async function GameBadge({ family, className = "" }: { family: string; className?: string }) {
  const label = GAME_DISPLAY[family as GameFamily]?.name ?? family;
  const [art, accent] = await Promise.all([resolveBadgeArt(family), getPosterAccentColor(family)]);

  return (
    <span
      title={label}
      className={"absolute bottom-1.5 left-1.5 h-16 w-11 overflow-hidden rounded-md bg-navy-950/80 shadow-lg " + className}
      style={{ border: `2px solid ${accent}` }}
    >
      {/* eslint-disable-next-line @next/next/no-img-element */}
      <img
        src={art.src}
        alt={label}
        className={art.isPoster ? "h-full w-full object-cover" : "h-full w-full object-contain p-1"}
      />
    </span>
  );
}

import Link from "next/link";
import { formatDownloads, SOURCE_LABEL, type ModSummary } from "@/lib/mods-catalog";
import { GameBadge } from "./GameBadge";
import { IconDownload, IconStar } from "./icons";

/**
 * One catalogue tile. Plain <img>, not next/image — the icon/gallery URLs
 * come from whichever source verified the mod (cdn.modrinth.com,
 * spigotmc.org, gcdn.thunderstore.io, ...), and next/image requires every
 * remote host to be allow-listed up front. The CSP already permits
 * `img-src https:`, so a plain tag renders every one of them with no
 * per-CDN config to maintain as new sources get verified.
 *
 * `showGameBadge` is for CROSS-GAME grids only (the homepage's mixed
 * featured/trending strips) — a single game's own page never sets it, the
 * game already being obvious from context there.
 *
 * The card's own clickable area (image + name/description) is a single
 * <Link> to the detail page, same as always. `footer` renders BELOW that
 * link but still inside this card's own rounded/bordered boundary — as a
 * sibling, not nested inside the <a>, because it carries real interactive
 * elements (QuickAddButton's select+button, or the "Order server"/download
 * buttons below) that can't legally nest inside an anchor. Callers that
 * don't pass `footer` (e.g. the related-mods strip on the detail pages) get
 * the plain card with no footer band at all, exactly as before.
 */
export function ModCard({
  mod,
  href,
  showGameBadge = false,
  footer,
  download,
}: {
  mod: ModSummary;
  href: string;
  showGameBadge?: boolean;
  /**
   * Server-availability action for this mod — StoreBrowser's QuickAddButton
   * when the viewer has a matching server, or a "no matching server yet"
   * prompt when they don't. Only the portal grids (which know who's signed
   * in) pass this.
   */
  footer?: React.ReactNode;
  /**
   * Real per-source download destination (resolveDownloadUrl's result, same
   * function the mod detail page's "Download file" / "View on X" button
   * already calls) — `undefined` (not passed) renders no download button at
   * all, `null` means it resolved to "nothing downloadable found".
   */
  download?: { url: string; direct: boolean } | null;
}) {
  const downloads = formatDownloads(mod.downloads);
  const hasFooterRow = footer !== undefined || download !== undefined;

  return (
    <div className="card card-hover group flex flex-col gap-0 overflow-hidden !p-0">
      <Link href={href} className="flex flex-1 flex-col gap-0">
        <div className="relative aspect-[16/10] w-full shrink-0 overflow-hidden bg-white/[0.04]">
          {mod.iconUrl ? (
            // eslint-disable-next-line @next/next/no-img-element
            <img
              src={mod.iconUrl}
              alt=""
              loading="lazy"
              className="h-full w-full object-cover transition-transform duration-300 group-hover:scale-[1.04]"
            />
          ) : (
            <div className="flex h-full w-full items-center justify-center text-3xl font-bold text-[var(--fg-muted)]">
              {mod.name.slice(0, 1)}
            </div>
          )}
          {mod.featured && (
            <span className="absolute left-2 top-2 rounded-full bg-brand-500/90 px-2 py-0.5 text-[10px] font-semibold uppercase tracking-wide text-white">
              Featured
            </span>
          )}
          {mod.avgRating != null && (
            <span className="absolute right-2 top-2 flex items-center gap-1 rounded-full bg-black/60 px-2 py-0.5 text-[11px] font-semibold text-amber-300">
              <IconStar size={11} filled />
              {mod.avgRating.toFixed(1)}
            </span>
          )}
          {showGameBadge && <GameBadge family={mod.gameFamily} />}
        </div>

        <div className="flex flex-1 flex-col gap-2 p-4">
          <div className="flex items-center gap-1.5 text-[11px] font-medium uppercase tracking-wide text-brand-300">
            {mod.gameFamilyLabel} <span className="text-[var(--fg-muted)]">· {mod.category}</span>
          </div>
          <h3 className="truncate text-sm font-semibold text-[var(--fg)] group-hover:text-brand-300">{mod.name}</h3>
          {mod.description && <p className="line-clamp-2 text-xs leading-relaxed text-[var(--fg-muted)]">{mod.description}</p>}
          <div className="mt-auto flex items-center justify-between pt-1 text-[11px] text-[var(--fg-muted)]">
            <span className="flex items-center gap-1">
              {downloads && (
                <>
                  <IconDownload size={12} /> {downloads}
                </>
              )}
            </span>
            {mod.verified && <span className="rounded-full bg-emerald-500/15 px-2 py-0.5 text-emerald-400">Verified</span>}
          </div>
        </div>
      </Link>

      {hasFooterRow && (
        <div className="flex items-center justify-between gap-2 border-t border-white/[0.06] px-4 py-2.5">
          {download ? (
            <a
              href={download.url}
              target="_blank"
              rel="noopener noreferrer nofollow"
              className="btn-secondary shrink-0 py-1 text-xs"
            >
              <IconDownload size={12} />
              {download.direct ? "Download" : `View on ${SOURCE_LABEL[mod.source] ?? mod.source}`}
            </a>
          ) : (
            <span />
          )}
          {footer}
        </div>
      )}
    </div>
  );
}

