228	/** Real Prev/Next + numbered pager, plus honest "X–Y of N mods" copy — no fake page counts. */
229	function Pager({
230	  page,
231	  totalPages,
232	  total,
233	  rangeFrom,
234	  rangeTo,
235	  hrefFor,
236	}: {
237	  page: number;
238	  totalPages: number;
239	  total: number;
240	  rangeFrom: number;
241	  rangeTo: number;
242	  hrefFor: (next: { page: number }) => string;
243	}) {
244	  const linkCls =
245	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/10 bg-white/[0.03] px-3 text-sm font-medium text-[var(--fg-muted)] transition-colors hover:border-brand-400/50 hover:text-[var(--fg)]";
246	  const disabledCls =
247	    "inline-flex h-9 min-w-9 items-center justify-center gap-1.5 rounded-lg border border-white/[0.06] bg-transparent px-3 text-sm font-medium text-[var(--fg-muted)]/40 cursor-not-allowed";
248	
249	  const windowStart = Math.max(1, page - 2);
250	  const windowEnd = Math.min(totalPages, page + 2);
251	  const pages: number[] = [];
252	  for (let i = windowStart; i <= windowEnd; i++) pages.push(i);
253	
254	  return (
255	    <div className="mt-8 flex flex-col items-center gap-3">
256	      <p className="text-xs text-[var(--fg-muted)]">
257	        {total === 0 ? "0 mods" : `${rangeFrom.toLocaleString()}–${rangeTo.toLocaleString()} of ${total.toLocaleString()} mods`}
258	      </p>
259	      {totalPages > 1 && (
260	        <nav className="flex flex-wrap items-center justify-center gap-2" aria-label="Mods pagination">
261	          {page > 1 ? (
262	            <Link href={hrefFor({ page: page - 1 })} rel="prev" className={linkCls} aria-label="Previous page">
263	              <IconArrow size={13} className="rotate-180" /> Prev
264	            </Link>
265	          ) : (
266	            <span className={disabledCls} aria-hidden>
267	              <IconArrow size={13} className="rotate-180" /> Prev
268	            </span>
269	          )}
270	
271	          {windowStart > 1 && (
272	            <>
273	              <Link href={hrefFor({ page: 1 })} className={linkCls}>
274	                1
275	              </Link>
276	              {windowStart > 2 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
277	            </>
278	          )}
279	
280	          {pages.map((n) =>
281	            n === page ? (
282	              <span
283	                key={n}
284	                aria-current="page"
285	                className="inline-flex h-9 min-w-9 items-center justify-center rounded-lg border border-brand-500/50 bg-brand-500/15 px-3 text-sm font-semibold text-brand-300"
286	              >
287	                {n}
288	              </span>
289	            ) : (
290	              <Link key={n} href={hrefFor({ page: n })} className={linkCls}>
291	                {n}
292	              </Link>
293	            )
294	          )}
295	
296	          {windowEnd < totalPages && (
297	            <>
298	              {windowEnd < totalPages - 1 && <span className="px-1 text-[var(--fg-muted)]">…</span>}
299	              <Link href={hrefFor({ page: totalPages })} className={linkCls}>
300	                {totalPages}
301	              </Link>
302	            </>
303	          )}
304	
305	          {page < totalPages ? (
